from pathlib import Path
import json
root=Path(__file__).resolve().parent
rows=[json.loads(x) for x in (root/'dev_records.jsonl').read_text().splitlines()]
issues={
 'squad-570a04be4103511400d594f7':('ambiguous','Question does not specify UK versus Hanover heir. Gold paragraph names Queen Victoria as UK heir and Ernest Augustus as Hanover successor.','Exclude from a strict gold capability gate unless a question repair is frozen separately; retain original output and denominator.'),
 'squad-5727cb4d4b864d1900163d37':('multiple_supported_answers','Paragraph identifies Cies, Ons, Salvora archipelagos plus Cortegada Island as the National Park. A semantically valid alternative could miss the sole annotation.','Accept Cortegada; also flag other named park islands/archipelagos for evidence-aware adjudication rather than automatically mark wrong.'),
 'squad-5730537d396df91900096074':('multiple_supported_answers','Question excludes University of Swaziland and Southern Nazarene, but paragraph also names Limkokwing University in addition to annotated Swaziland Christian University.','Accept Swaziland Christian University and Limkokwing University of Creative Technology as supported alternatives.'),
 'squad-572ecc0fcb0c0d14000f157f':('unsupported_narrowing','Gold sentence jointly describes Laurentian Highlands, Interior Plains and Interior Highlands stretching to Arctic Ocean; question singles out Interior Highlands. It does not securely support that narrower geographic claim.','Exclude from a strict capability gate; retain original public annotation and report question/evidence mismatch.'),
 'squad-572ea993cb0c0d14000f1417':('question_evidence_scope_mismatch','Radiocarbon bound concerns parchments, while question asks when manuscripts were produced. Materials and writing dates need not coincide.','Mark wording imprecise; do not interpret a model correction as automatic factual error.'),
 'squad-572fe5e8b2c2fd1400568583':('question_evidence_conflict','Question asks transmitter, but answer and evidence say 30 MHz receiver. Beam is also misspelled Bean.','Exclude from strict capability gate; a correction that this is a receiver is valid evidence-grounded behavior.'),
 'squad-572774785951b619008f8a4b':('historical_snapshot','Question omits year but gold paragraph explicitly gives 2000 census statistics.','Evaluate under supplied historical passage, not present-day Ann Arbor household statistics.'),
 'squad-570b09a96b8089140040f704':('historical_future_statement','Question asks planned refit from a historical Wikipedia snapshot; current refit state is not asserted.','Evaluate passage-conditioned plan, not independently updated 2026 fact.'),
 'squad-572b951ef75d5e190021fe5f':('comparative_wording','Question asks most expensive; passage only says online often more expensive than face-to-face.','Answer Online courses is supported as a relative comparison, but not a universal cost ranking.')
}
a=[]
for r in rows:
 code,why,action=issues.get(r['qid'],('supported_under_evidence_snapshot','Annotated answer directly answers the question within the supplied paragraph.','Use as passage-grounded capability evidence; exact matching remains a text proxy.'))
 a.append({'qid':r['qid'],'title':r['title'],'question':r['question'],'annotated_answers':r['answers'],'assessment':code,'rationale':why,'scoring_action':action,'reviewer':'single source-text audit; not blinded independent human annotation','model_outputs_used':False})
result={'status':'SOURCE_REVIEW_COMPLETED_BEFORE_INSPECTING_NEW_MODEL_OUTPUTS','reviewed':30,'strict_gate_exclusions':[x['qid'] for x in a if x['assessment'] in ['ambiguous','unsupported_narrowing','question_evidence_conflict']], 'note':'No sample replacements or question edits were made after freezing. Keep full 30-question public-annotation results, and give strict-gate denominator separately if used; do not claim original 24/30 gate passed on a changed denominator.', 'questions':a}
(root/'dev_source_quality_audit.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
(root/'Dev_Source_Quality_Audit.md').write_text('# Frozen SQuAD development-question source audit\n\nSingle source review of the 30 fixed question/gold paragraphs, without inspecting new model outputs. This is not two-human blinded annotation. No question replacements or label overwrites were made.\n\nThree cases should be excluded from a strict capability denominator only if that denominator change is explicitly reported: Hanover succession ambiguity, Interior Highlands narrowing, and transmitter/receiver conflict. The original 30-question annotation-matching results must remain available. Quran parchment/writing dates and several multiple-answer or historical-snapshot cases need adjudication.\n\n'+'\n'.join('## '+x['qid']+' — '+x['title']+'\n\n'+x['assessment']+': '+x['rationale']+'\n\n'+x['scoring_action']+'\n' for x in a))
print(json.dumps({'reviewed':30,'strict_gate_exclusions':result['strict_gate_exclusions']}))
